package com.bank.sla;

import java.util.logging.*;

public class MaxOnesDemo {
    private static final Logger log = Logger.getLogger(MaxOnesDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        UptimeAnalyzer analyzer = new UptimeAnalyzer();

        // 1 = up, 0 = down
        int[] uptime = {1, 1, 0, 0, 1, 1, 1, 0, 1};
        int k = 2; // may excuse 2 down-days
        int run = analyzer.longestAvailability(uptime, k);
        log.info(() -> "Longest availability run with " + k + " excused: " + run);
    }
}

