class UptimeAnalyzer {
    private static final Logger log = Logger.getLogger(UptimeAnalyzer.class.getName());

    // Variable window, at most k zeros. O(n) time, O(1) space.
    int longestAvailability(int[] a, int k) {
        int left = 0, zeros = 0, best = 0;
        for (int right = 0; right < a.length; right++) {
            if (a[right] == 0) zeros++;         // a down-day entered
            while (zeros > k) {                 // over budget → shrink
                if (a[left] == 0) zeros--;
                left++;
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
